import { test, expect } from '@playwright/test';

test.describe('Form Field Accessibility - Associated Labels', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should have accessible labels for screen reader users', async ({ page }) => {
    // Verify form is visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Verify all form fields have associated labels
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');
    const passwordInput = page.getByLabel('Password');
    const confirmPasswordInput = page.getByLabel('Confirm Password');
    const submitButton = page.getByRole('button', { name: /submit/i });

    await expect(nameInput).toBeVisible();
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();
    await expect(confirmPasswordInput).toBeVisible();

    // Verify labels are associated with their respective inputs
    await expect(nameInput).toHaveAttribute('aria-label', 'Full Name');
    await expect(emailInput).toHaveAttribute('aria-label', 'Email Address');
    await expect(passwordInput).toHaveAttribute('aria-label', 'Password');
    await expect(confirmPasswordInput).toHaveAttribute('aria-label', 'Confirm Password');

    // Verify form is accessible using screen reader
    await page.evaluate(() => {
      const screenReader = navigator.screenReader || navigator.msScreenReader;
      if (screenReader) {
        screenReader.speak('Form with accessible labels');
      }
    });

    // Verify form is navigable using keyboard
    await page.keyboard.press('Tab');
    await expect(nameInput).toBeFocused();

    await page.keyboard.press('Tab');
    await expect(emailInput).toBeFocused();

    await page.keyboard.press('Tab');
    await expect(passwordInput).toBeFocused();

    await page.keyboard.press('Tab');
    await expect(confirmPasswordInput).toBeFocused();

    // Verify submit button is accessible
    await expect(submitButton).toBeFocused();

    // Verify error messages are accessible
    const errorMessage = page.getByText('Please fill all fields');
    await expect(errorMessage).toBeVisible();

    // Verify success message is accessible
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify form is accessible after submission
    await submitButton.click();
    await expect(successMessage).toBeVisible();
  });

  test('should handle form validation errors gracefully', async ({ page }) => {
    // Fill in all fields except confirm password
    const nameInput = page.getByLabel('Full Name');
    const emailInput = page.getByLabel('Email Address');
    const passwordInput = page.getByLabel('Password');
    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');
    await passwordInput.fill('SecurePassword123');

    // Submit form without confirm password
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('Confirm password is required');
    await expect(errorMessage).toBeVisible();

    // Verify form is still accessible
    await expect(nameInput).toBeFocused();
    await expect(emailInput).toBeFocused();
    await expect(passwordInput).toBeFocused();

    // Verify error message is announced by screen reader
    await page.evaluate(() => {
      const screenReader = navigator.screenReader || navigator.msScreenReader;
      if (screenReader) {
        screenReader.speak('Confirm password is required');
      }
    });

    // Verify error message is visible
    await expect(errorMessage).toBeVisible();

    // Verify form is still navigable using keyboard
    await page.keyboard.press('Tab');
    await expect(nameInput).toBeFocused();

    await page.keyboard.press('Tab');
    await expect(emailInput).toBeFocused();

    await page.keyboard.press('Tab');
    await expect(passwordInput).toBeFocused();

    // Verify error message is still visible
    await expect(errorMessage).toBeVisible();

    // Verify success message is not visible
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();

    // Verify form is still accessible after error
    await expect(nameInput).toBeFocused();
    await expect(emailInput).toBeFocused();
    await expect(passwordInput).toBeFocused();
  });
});
